import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function designed to exhibit specific ELA features.
    This function combines a scaled sigmoid, a polynomial term, and a product of sines to create a complex landscape.

    Formula:
    f(x) = 0.5 * sigmoid(x[0] + x[1]) + 0.2 * (x[0]**2 - x[1]**3) + 0.3 * np.sin(x[0]) * np.sin(2*x[1])
    where sigmoid(z) = 1 / (1 + exp(-z))
    """

    def sigmoid(z):
        return 1 / (1 + np.exp(-z))

    return 0.5 * sigmoid(x[0] + x[1]) + 0.2 * (x[0]**2 - x[1]**3) + 0.3 * np.sin(x[0]) * np.sin(2*x[1])
